import type { LibraryBook, LibraryBookDetail } from "@/types";
import { summaryOf, toLibraryBookDetail, type BookDetailDto } from "@/lib/libraryBook";
import snapshot from "./library.catalog.generated.json";

/**
 * Build-time snapshot of the whole library (every book with its contents),
 * generated by `app.scripts.export_catalog`. For server components only:
 * static book pages, the sitemap and first paint of the library grid.
 * Importing it from a client component would ship the whole file to browsers.
 */
export const catalog: LibraryBookDetail[] = (snapshot.books as BookDetailDto[]).map(toLibraryBookDetail);
export const catalogGenres: { genre: string; count: number }[] = snapshot.genres;

export const catalogBySlug = (slug: string) => catalog.find((b) => b.slug === slug);

/** Books closest in meaning (vector search, captured at export); same author / genre when not embedded yet. */
export function similarTo(book: LibraryBookDetail, limit = 8): { books: LibraryBook[]; byMeaning: boolean } {
  const picks = book.similar.map(catalogBySlug).filter((b): b is LibraryBookDetail => !!b);
  if (picks.length) return { books: picks.slice(0, limit).map(summaryOf), byMeaning: true };
  return { books: sameShelf(book, limit), byMeaning: false };
}

/** Same author first, then the same genre, in shelf order. */
export function sameShelf(book: LibraryBook, limit = 8): LibraryBook[] {
  const score = (b: LibraryBook) => (b.author === book.author ? 2 : 0) + (b.genre === book.genre ? 1 : 0);
  return catalog
    .filter((b) => b.id !== book.id)
    .map((b, i) => ({ b, s: score(b), i }))
    .sort((x, y) => y.s - x.s || x.i - y.i)
    .slice(0, limit)
    .map(({ b }) => summaryOf(b));
}
